def comps(grid):
 R,C=len(grid),len(grid[0]);seen=set();out=[]
 for r in range(R):
  for c in range(C):
   if grid[r][c]==7 and (r,c) not in seen:
    q=[(r,c)];seen.add((r,c));co=[]
    for p in q:
     co.append(p);r1,c1=p
     for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
      n=(r1+dr,c1+dc)
      if 0<=n[0]<R and 0<=n[1]<C and grid[n[0]][n[1]]==7 and n not in seen:seen.add(n);q.append(n)
    out.append(co)
 return out
